6	/// The dashboard feature's one port (RNF06) — `features/dashboard/
7	/// presentation` depends on this abstract class only, never
8	/// `features/dashboard/data` directly. Returns `Either<Failure, T>`
9	/// (RNF09).
10	abstract class DashboardRepository {
11	  /// Calls `dashboard-aggregate-get` (`ApiClient.get`, [period] sent as the
12	  /// one required `period` query parameter) — a thin pass-through, no
13	  /// cache (Boundaries/Never: "cache the aggregate", AD-15 exclusion).
14	  /// `DashboardCubit.load()` is this method's one call site, always with
15	  /// `period: 'all'` (Boundaries: "fixed; no period selector exists
16	  /// anywhere in the product"); [period] stays a plain `String` (the
17	  /// contract's own `openapi.yaml` enum values) rather than a dedicated
18	  /// enum, since nothing else in this app will ever pass a different one.
19	  Future<Either<Failure, DashboardAggregate>> getAggregate({
20	    required String period,
21	  });
22	}
