7	/// The dashboard feature's one remote data source — `dashboard-aggregate-
8	/// get`, called by `x-cerne-function` name only (AGENTS.md), [period] sent
9	/// as the one required `period` query parameter. Mirrors
10	/// `ExportRemoteDataSource`'s own try/catch-to-`malformedResponse` shape
11	/// for its decode step (RNF09).
12	class DashboardRemoteDataSource {
13	  DashboardRemoteDataSource(this._apiClient);
14	
15	  final ApiClient _apiClient;
16	
17	  Future<Either<Failure, DashboardAggregateDto>> getAggregate({
18	    required String period,
19	  }) async {
20	    final result = await _apiClient.get(
21	      'dashboard-aggregate-get',
22	      queryParameters: {'period': period},
23	    );
24	    return result.flatMap((json) {
25	      try {
26	        final data = json['data'] as Map<String, dynamic>;
27	        return right(DashboardAggregateDto.fromJson(data));
28	      } catch (error) {
29	        return left(Failure.malformedResponse(message: error.toString()));
30	      }
31	    });
32	  }
33	}
