1	/// `GET /dashboard/aggregate`'s own domain shape (spec-8-1) — the chart
2	/// section only ever needs the period total and each bucket's own count
3	/// (Code Map: "domain `DashboardAggregate` exposes only
4	/// `totalCount`/`bucketCounts`"); every other contract field
5	/// (`buckets[].date`/`.sources`, `totals.sources`) stops at
6	/// `DashboardAggregateDto`, never reaching this layer. No AI narrative
7	/// field either — that's Story 8.2, explicitly out of scope here (Intent).
8	class DashboardAggregate {
9	  const DashboardAggregate({
10	    required this.totalCount,
11	    required this.bucketCounts,
12	  });
13	
14	  /// `totals.count` — the one value the 0/1/>30/2..30 state matrix
15	  /// (Boundaries) branches on.
16	  final int totalCount;
17	
18	  /// One count per contract `buckets[]` entry, in the same (chronological)
19	  /// order the backend returns them — `DashboardChartSection`'s own
20	  /// condensation/bar-height logic relies on that order being preserved
21	  /// end to end (`DashboardAggregateDto.toDomain()` maps it straight
22	  /// across, with no reordering of its own).
23	  final List<int> bucketCounts;
24	
25	  @override
26	  bool operator ==(Object other) =>
27	      identical(this, other) ||
28	      (other is DashboardAggregate &&
29	          other.totalCount == totalCount &&
30	          _listEquals(other.bucketCounts, bucketCounts));
31	
32	  @override
33	  int get hashCode => Object.hash(totalCount, Object.hashAll(bucketCounts));
34	
35	  @override
36	  String toString() =>
37	      'DashboardAggregate(totalCount: $totalCount, '
38	      'bucketCounts: $bucketCounts)';
39	}
40	
41	bool _listEquals(List<int> a, List<int> b) {
42	  if (a.length != b.length) {
43	    return false;
44	  }
45	  for (var i = 0; i < a.length; i++) {
46	    if (a[i] != b[i]) {
47	      return false;
48	    }
49	  }
50	  return true;
51	}
