22	/// The project's single `get_it` instance — exactly one DI container exists
23	/// (architecture spine). Every feature's `registerXFeature()` registers
24	/// through this same `sl`, never a second container.
25	final sl = GetIt.instance;
26	
27	/// Bootstraps core infrastructure: loads `.env`, then registers
28	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
29	/// interceptors) and `ApiClient` through `sl` — the `dio` +
30	/// `flutter_secure_storage` + `get_it` integration spike this story proves
31	/// before anything else is built on top of it.
32	Future<void> setupCoreDependencies() async {
33	  await dotenv.load(fileName: '.env');
34	
35	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
36	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
37	
38	  sl.registerLazySingleton<FlutterSecureStorage>(
39	    () => const FlutterSecureStorage(),
40	  );
41	
42	  sl.registerLazySingleton<AccessTokenProvider>(
43	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
44	  );
45	
46	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
47	
48	  // Story 1.5 — `dispose:` wires `SessionExpiryNotifier.dispose()` into
49	  // `get_it`'s own reset lifecycle, same rationale as `SessionRepository`'s
50	  // own registration below. Registration order here is cosmetic, not
51	  // load-bearing: `registerLazySingleton` only builds its instance on first
52	  // `sl<T>()` access, so `ApiClient`'s factory can resolve this dependency
53	  // correctly regardless of which of the two is registered first.
54	  sl.registerLazySingleton<SessionExpiryNotifier>(
55	    () => SessionExpiryNotifierImpl(),
56	    dispose: (notifier) => notifier.dispose(),
57	  );
58	
59	  sl.registerLazySingleton<Dio>(() {
60	    final dio = Dio(
61	      BaseOptions(
62	        // Design note (docs/input is silent on exact numbers): a stalled
63	        // connection must still fail instead of hanging indefinitely.
64	        connectTimeout: const Duration(seconds: 10),
65	        receiveTimeout: const Duration(seconds: 30),
66	        sendTimeout: const Duration(seconds: 30),
67	      ),
68	    );
69	    dio.interceptors.add(
70	      HeaderInterceptor(
71	        anonKey: supabaseAnonKey,
72	        accessTokenProvider: sl<AccessTokenProvider>(),
73	      ),
74	    );
75	    dio.interceptors.add(RetryInterceptor(dio));
76	    return dio;
77	  });
78	
79	  sl.registerLazySingleton<ApiClient>(
80	    () => ApiClient(
81	      dio: sl<Dio>(),
82	      urlBuilder: sl<UrlBuilder>(),
83	      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
84	    ),
85	  );
86	
87	  registerAuthFeature();
88	  registerVaultFeature();
89	  registerAccountFeature();
90	
91	  // Story 3.1 — the app's first `hive_ce` usage: `initFlutter()` must
92	  // complete before `registerEntriesFeature()` opens its box (Code Map).
93	  await Hive.initFlutter();
94	  await registerEntriesFeature();
95	  registerCaptureFeature();
96	  // spec-6-1 — `registerChatFeature()` opens its own two Hive boxes, same
97	  // `Hive.initFlutter()`-must-run-first requirement `registerEntriesFeature()`
98	  // already documents for itself.
99	  await registerChatFeature();
100	  // spec-7-1 — no Hive box of its own (AD-15: export jobs are never
101	  // persisted locally), so unlike the call above this one needs no
102	  // `Hive.initFlutter()` ordering and isn't `async`.
103	  registerExportFeature();
104	  // spec-8-1 — called after `registerEntriesFeature()` above, since
105	  // `DashboardCubit` depends on the `PendingEntryWriteTracker` that
106	  // registration provides (Code Map); every registration involved is
107	  // `registerLazySingleton`, though, so this call order isn't itself
108	  // load-bearing (review finding, `dashboard_injection.dart`'s own doc
109	  // comment) — `PendingEntryWriteTracker` is only resolved lazily, on
110	  // first use. No Hive box of its own either (Boundaries/Never: "cache
111	  // the aggregate", AD-15 exclusion), so this isn't `async` either.
112	  registerDashboardFeature();
113	}
114	
115	/// Test/teardown helper — resets the single `get_it` instance so each test
116	/// bootstraps its own clean registrations.
117	Future<void> resetCoreDependencies() => sl.reset();
