23	/// Same plain (non-mocktail) fake shape as
24	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
25	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
26	/// real stream the cubit (built from this fake, not mocked) actually
27	/// subscribes to. `biometricEnabledStream` is a plain broadcast stream, not
28	/// a `Stream.multi` replay wrapper (unlike the production repository) —
29	/// `AccountSettingsCubit`'s own constructor already reads
30	/// [currentBiometricEnabled] directly for its initial state, so no replay
31	/// machinery is needed for a fake with exactly one subscriber.
32	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
33	  bool _value = true;
34	  final _controller = StreamController<bool>.broadcast();
35	
36	  /// The next `setBiometricEnabled()` call's own result — defaults to a
37	  /// failure so a test must opt in to the success path explicitly, same
38	  /// convention as the cubit-level fake.
39	  Either<Failure, Unit> setBiometricEnabledResult = left(
40	    const Failure.malformedResponse(message: 'fake: not configured'),
41	  );
42	
43	  /// Lets a test hold `setBiometricEnabled()` unresolved, to observe
44	  /// `state.isSaving` mid-flight (review finding: the `Switch` must
45	  /// disable itself while a toggle is in flight).
46	  Completer<void>? setBiometricEnabledGate;
47	
48	  @override
49	  bool get currentBiometricEnabled => _value;
50	
51	  @override
52	  Stream<bool> get biometricEnabledStream => _controller.stream;
53	
54	  @override
55	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
56	
57	  @override
58	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
59	    final gate = setBiometricEnabledGate;
60	    if (gate != null) {
61	      await gate.future;
62	    }
63	    final previous = _value;
64	    _emit(enabled);
65	    final result = setBiometricEnabledResult;
66	    if (result.isLeft()) {
67	      _emit(previous);
68	    }
69	    return result;
70	  }
71	
72	  @override
73	  Future<void> dispose() => _controller.close();
74	
75	  void _emit(bool value) {
76	    _value = value;
77	    _controller.add(value);
78	  }
79	}
