142	/// (`back_arrow_header_test.dart`'s own rationale) — needs a real
143	/// `GoRouter` ancestor to resolve, hence this minimal two-route wrapper
144	/// rather than a bare `MaterialApp`.
145	GoRouter _routerWith(Widget screen) {
146	  return GoRouter(
147	    initialLocation: '/configuracoes',
148	    routes: [
