155	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
156	/// pair and pumps the real screen around it, registering both for cleanup.
157	///
158	/// Deliberately constructed *inside* each `testWidgets` body (via this
159	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
160	/// `package:test`'s own per-test zone, a different zone than the one
161	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
162	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
163	/// subscription to the repository's stream, set up in its constructor)
164	/// created in that outer zone does not reliably get its pending events
165	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
166	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
167	/// widget never rebuilt, no matter how many `pump()` calls followed.
168	/// Constructing the cubit here, inside the same zone `tester.pump()`
169	/// drains, avoids the mismatch entirely.
170	Future<(_FakeAccountSettingsRepository, AccountSettingsCubit)> _pumpScreen(
171	  WidgetTester tester,
172	) async {
173	  final fakeRepository = _FakeAccountSettingsRepository();
174	  final cubit = AccountSettingsCubit(fakeRepository);
175	  addTearDown(() => cubit.close());
176	  addTearDown(fakeRepository.dispose);
177	
178	  final router = _routerWith(
179	    AccountSettingsScreen(cubit: cubit, dashboardCubit: _buildDashboardCubit()),
180	  );
181	  addTearDown(router.dispose);
182	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
183	
184	  return (fakeRepository, cubit);
185	}
