22	  test('a thin pass-through (Code Map): forwards period verbatim and maps '
23	      'the DTO to its own domain shape via DashboardAggregateDto.toDomain, '
24	      'with no caching of its own', () async {
25	    const sources = DashboardSourcesDto(manual: 1, audio: 0, photo: 0, chat: 0);
26	    when(() => mockDataSource.getAggregate(period: 'all')).thenAnswer(
27	      (_) async => right(
28	        const DashboardAggregateDto(
29	          buckets: [
30	            DashboardBucketDto(date: '2026-01-01', count: 1, sources: sources),
31	          ],
32	          totals: DashboardTotalsDto(count: 1, sources: sources),
33	        ),
34	      ),
35	    );
36	
37	    final result = await repository.getAggregate(period: 'all');
38	
39	    expect(result.isRight(), isTrue);
40	    result.match((_) => fail('expected Right'), (aggregate) {
41	      expect(aggregate.totalCount, 1);
42	      expect(aggregate.bucketCounts, [1]);
43	    });
44	    verify(() => mockDataSource.getAggregate(period: 'all')).called(1);
45	  });
